SELECT A.COMPANY_CODE ,A.CONT_STATUS ,(SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'C008' AND CODE = A.CONT_STATUS) CONT_STATUS_TEXT ,(SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'C007' AND CODE = A.COMPANY_TYPE) COMPANY_TYPE ,(SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'C006' AND CODE = A.BIZ_TYPE) BIZ_TYPE ,(SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.COMPANY_CODE) COMPANY_NAME ,(SELECT IRS_NO FROM ICOMCMPY WHERE COM_CODE = A.COMPANY_CODE) BIZMN_REGST_NO ,A.CONT_NO || '-' || A.CONT_COUNT AS CONT_NO ,A.CONT_COUNT ,A.CONT_NO AS CONT_NO_HID ,A.APPR_STATUS ,A.CONT_TITLE ,B.FORM_NAME ,DECODE(LENGTH(A.CONT_DATE), 8, SUBSTR(A.CONT_DATE, 1, 4)||'/'||SUBSTR(A.CONT_DATE, 5, 2)||'/'||SUBSTR(A.CONT_DATE, 7, 2), A.CONT_DATE) CONT_DATE ,DECODE(LENGTH(A.START_DATE), 8, SUBSTR(A.START_DATE, 1, 4)||'/'||SUBSTR(A.START_DATE, 5, 2)||'/'||SUBSTR(A.START_DATE, 7, 2), A.START_DATE)START_DATE ,DECODE(LENGTH(A.END_DATE), 8, SUBSTR(A.END_DATE, 1, 4)||'/'||SUBSTR(A.END_DATE, 5, 2)||'/'||SUBSTR(A.END_DATE, 7, 2), A.END_DATE)END_DATE ,A.COP_DEPT_NAME ,(SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = A.USER_ID) USER_NAME ,C.RJ_REASON ,DECODE(LENGTH(C.RJ_DATE), 8, SUBSTR(C.RJ_DATE, 1, 4)||'/'||SUBSTR(C.RJ_DATE, 5, 2)||'/'||SUBSTR(C.RJ_DATE, 7, 2), C.RJ_DATE)RJ_DATE ,(SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'C009' AND CODE = C.RJ_TYPE) RJ_TYPE ,(SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = C.ADD_USER_ID) RJ_USER FROM ICOMECCT A, ICOMECCF B, ( SELECT X.RJ_NO ,X.CONT_NO ,X.CONT_COUNT ,X.RJ_REASON ,X.RJ_DATE ,X.RJ_TYPE ,X.ADD_USER_ID FROM (SELECT MAX(RJ_NO) RJ_NO FROM ICOMECRJ GROUP BY CONT_NO, CONT_COUNT ) Z, ICOMECRJ X WHERE Z.RJ_NO = X.RJ_NO ) C WHERE A.FORM_NO = B.FORM_NO AND A.CONT_NO = C.CONT_NO(+) AND A.CONT_COUNT = C.CONT_COUNT(+) AND A.COMPANY_CODE = #{st_com_code}
AND A.CONT_TITLE LIKE '%'|| #{st_cont_title} || '%'
AND A.START_DATE >= #{st_from_date}
AND A.END_DATE <= #{st_to_date}
AND A.CONT_STATUS = #{st_cont_status}
ORDER BY A.CONT_NO DESC, A.CONT_COUNT DESC, C.RJ_NO ASC
